"christian-2017-sutherland-springs-church-shooting-246":{title:"הירי בכנסיית סאת'רלנד ספרינגס",location:"טקסס, ארצות הברית",story:"חמוש פתח באש במהלך תפילת יום ראשון בכנסייה הבפטיסטית הראשונה בסאת'רלנד ספרינגס והרג 26 בני אדם. החוקרים קבעו שהמתקפה נבעה בעיקר מסכסוך משפחתי ואישי ולא מאידאולוגיה אנטי־נוצרית.",context:"ירי המוני / מתקפה בכנסייה",aftermath:"הטבח עורר דיון נרחב בארצות הברית על אלימות בנשק, אלימות במשפחה וביטחון במקומות תפילה.",sourceStatus:"המתקפה מתועדת היטב. היא נכללת משום שקהילה נוצרית הותקפה בזמן תפילה, אך אין להציג את המניע בטעות כרדיפה דתית."},
"christian-2017-marawi-siege-devastates-christian-and-muslim-communities-247":{title:"המצור על מראווי מחריב קהילות נוצריות ומוסלמיות",location:"מראווי, הפיליפינים",story:"חמושים המזוהים עם דאעש השתלטו על חלקים ממראווי, לקחו בני ערובה ותקפו כנסיות בזמן שכוחות הפיליפינים ניהלו קרב עירוני שנמשך חמישה חודשים. רוב תושבי העיר היו מוסלמים וסבלו מעקירה המונית.",context:"מרד ג'יהאדיסטי / התקפות על כנסיות / מלחמה עירונית",aftermath:"הקרבות החריבו חלקים גדולים מן העיר ועקרו מאות אלפים. מוסדות וסמלים נוצריים הותקפו במכוון, אך האסון פגע בראש ובראשונה באוכלוסיית העיר כולה.",sourceStatus:"סמלים ואנשי כמורה נוצרים הותקפו במכוון, אך רוב העקורים היו מוסלמים והמצור החריב את העיר כולה."},
"christian-2018-surabaya-church-bombings-248":{title:"פיגועי הכנסיות בסורבאיה",location:"סורבאיה, אינדונזיה",story:"בני משפחה אחת ביצעו פיגועי התאבדות בשלוש כנסיות נוצריות ביום ראשון בבוקר. הרשויות באינדונזיה קשרו את התוקפים לרשת בהשראת דאעש.",context:"טרור / פיגועים בכנסיות",aftermath:"הפיגועים זעזעו את אינדונזיה והובילו להגברת צעדי הביטחון והמאבק ברשתות קיצוניות, לצד ביטויי סולידריות בין קהילות דתיות.",sourceStatus:"הפיגועים והרשת הקיצונית מתועדים היטב."},
"christian-2018-central-african-republic-church-and-mosque-attacks-deepen-communal-conflict-249":{title:"התקפות על כנסיות ומסגדים ברפובליקה המרכז־אפריקאית מעמיקות את הסכסוך הקהילתי",location:"הרפובליקה המרכז־אפריקאית",story:"קבוצות חמושות תקפו כנסיות, מסגדים ואזרחים בזמן שהסכסוך נמשך בין פלגים המזוהים לעיתים קרובות עם קהילות נוצריות או מוסלמיות. מנהיגי דת הזהירו שוב ושוב מפני הצגת המלחמה בפשטות כנוצרים נגד מוסלמים.",context:"סכסוך קהילתי / התקפות על מקומות תפילה",aftermath:"האלימות גרמה להרג ולעקירה והעמיקה את ההפרדה הקהילתית, אך מנהיגים נוצרים ומוסלמים המשיכו גם לשתף פעולה ביוזמות שלום ופיוס.",sourceStatus:"הדת חפפה לזהויות פוליטיות, אזוריות ומיליציוניות. מנהיגים דתיים נוצרים ומוסלמים שיתפו פעולה גם בבניית שלום."},
"christian-2019-easter-sunday-bombings-in-sri-lanka-250":{title:"פיגועי יום ראשון של חג הפסחא בסרי לנקה",location:"סרי לנקה",story:"פיגועי התאבדות מתואמים פגעו בכנסיות במהלך תפילות חג הפסחא ובמלונות יוקרה והרגו יותר מ־250 בני אדם. הרשויות ייחסו את הפיגועים לקיצונים אסלאמיסטים מקומיים שקיבלו השראה מדאעש.",context:"טרור / התקפות על כנסיות ואזרחים",aftermath:"הפיגועים גרמו לטראומה לאומית, להגברת האבטחה ולחקירות סביב רשתות קיצוניות וכשלים מודיעיניים, והעמיקו מתחים בין קהילות.",sourceStatus:"הפיגועים והיעדים מתועדים היטב; החקירות בחנו רשתות מקומיות וכשלי מודיעין."}
